<?php include '_layout_start.php'; $pdo=db(); $status=$_GET['status'] ?? ''; $course=$_GET['course'] ?? ''; if($pdo){$where=[];$params=[]; if($status){$where[]='status=?';$params[]=$status;} if($course){$where[]='course_interested LIKE ?';$params[]='%'.$course.'%';} $sql='SELECT * FROM leads'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY created_at DESC LIMIT 300'; $stmt=$pdo->prepare($sql);$stmt->execute($params);$leads=$stmt->fetchAll();} else {$leads=fallback_leads(); $leads=array_reverse($leads);} ?><h1>Leads</h1><div class="lead-box mb-4"><form class="row g-2"><div class="col-md-4"><input class="form-control" name="course" placeholder="Filter by course" value="<?= h($course) ?>"></div><div class="col-md-4"><select class="form-select" name="status"><option value="">All Status</option><?php foreach(['New Lead','Wrong Number','Not Picked','Call Back Later','Interested','Not Interested','Admission Done','Follow-up Required'] as $s): ?><option <?= $status===$s?'selected':'' ?>><?= h($s) ?></option><?php endforeach; ?></select></div><div class="col-md-4"><button class="btn btn-primary">Filter</button> <a class="btn btn-secondary" href="export-leads.php">Export CSV</a></div></form></div><div class="table-responsive bg-white rounded-4 shadow-sm"><table class="table table-hover align-middle"><thead><tr><th>Date</th><th>Name</th><th>Mobile</th><th>Course</th><th>City</th><th>Status</th><th>Temp.</th><th>Source</th><th></th></tr></thead><tbody><?php foreach($leads as $l): ?><tr><td><?= h($l['created_at'] ?? '') ?></td><td><?= h($l['student_name'] ?? '') ?></td><td><?= h($l['mobile'] ?? '') ?></td><td><?= h($l['course_interested'] ?? '') ?></td><td><?= h($l['city'] ?? '') ?></td><td><?= h($l['status'] ?? '') ?></td><td><?= h($l['lead_temperature'] ?? '') ?></td><td><?= h($l['source'] ?? '') ?></td><td><?php if($pdo): ?><a class="btn btn-sm btn-primary" href="lead-edit.php?id=<?= h($l['id']) ?>">Update</a><?php endif; ?></td></tr><?php endforeach; ?></tbody></table></div><?php include '_layout_end.php'; ?>
